BEGIN;
DO $$ BEGIN IF to_regclass('public.creator_receipts') IS NULL OR to_regclass('public.post_photos') IS NULL THEN RAISE EXCEPTION 'Reconcile modules through 0064 first';END IF;IF to_regclass('public.creator_partnerships') IS NOT NULL THEN RAISE EXCEPTION 'Creator Studio exists; inspect before replay';END IF;END $$;
ALTER TABLE public.creator_commerce ADD COLUMN min_price_cents integer NOT NULL DEFAULT 50 CHECK(min_price_cents>=50);
ALTER TABLE public.creator_commerce ADD COLUMN max_price_cents integer NOT NULL DEFAULT 1000000 CHECK(max_price_cents<=1000000);
ALTER TABLE public.creator_commerce ADD COLUMN recommended_price_cents integer NOT NULL DEFAULT 2999;
ALTER TABLE public.creator_commerce ADD CONSTRAINT creator_price_range CHECK(min_price_cents<=recommended_price_cents AND recommended_price_cents<=max_price_cents);
CREATE FUNCTION public.creator_price_limits() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT jsonb_build_object('minimum',min_price_cents,'maximum',max_price_cents,'recommended',recommended_price_cents) FROM creator_commerce WHERE singleton $$;
CREATE FUNCTION public.guard_creator_price() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM creator_commerce WHERE NEW.price_cents BETWEEN min_price_cents AND max_price_cents) THEN RAISE EXCEPTION 'Price is outside configured monthly bounds';END IF;RETURN NEW;END $$;
CREATE TRIGGER creator_price_bounds BEFORE INSERT OR UPDATE OF price_cents ON public.creator_offers FOR EACH ROW EXECUTE FUNCTION public.guard_creator_price();
CREATE FUNCTION public.configure_creator_prices(p_min integer,p_max integer,p_recommended integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF NOT has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admins only';END IF;UPDATE creator_commerce SET min_price_cents=p_min,max_price_cents=p_max,recommended_price_cents=p_recommended WHERE singleton;INSERT INTO moderation_actions(actor_id,target_type,target_id,action) VALUES(auth.uid(),'commerce','memberships','price_bounds_updated');END $$;
CREATE TABLE public.creator_partnerships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trainer_id uuid NOT NULL REFERENCES auth.users(id),sender_id uuid NOT NULL REFERENCES auth.users(id),name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120),organization text NOT NULL CHECK(length(trim(organization)) BETWEEN 1 AND 160),email text NOT NULL CHECK(email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' AND length(email)<=254),collaboration text NOT NULL CHECK(length(trim(collaboration)) BETWEEN 1 AND 80),description text NOT NULL CHECK(length(trim(description)) BETWEEN 20 AND 4000),budget text NOT NULL DEFAULT '' CHECK(length(budget)<=160),timeline text NOT NULL DEFAULT '' CHECK(length(timeline)<=160),status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','discussion','accepted','declined','archived')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX creator_partnership_inbox ON public.creator_partnerships(trainer_id,created_at DESC);
CREATE INDEX creator_partnership_rate ON public.creator_partnerships(sender_id,created_at);
CREATE FUNCTION public.submit_creator_partnership(p_trainer uuid,p_name text,p_organization text,p_email text,p_type text,p_description text,p_budget text DEFAULT '',p_timeline text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE result uuid;
BEGIN
 IF auth.uid() IS NULL OR auth.uid()=p_trainer OR NOT account_can_act(auth.uid(),false) OR NOT trainer_is_eligible(p_trainer,false) OR EXISTS(SELECT 1 FROM message_controls WHERE blocked AND ((user_id=auth.uid() AND other_id=p_trainer) OR (user_id=p_trainer AND other_id=auth.uid()))) THEN RAISE EXCEPTION 'Partnership inquiry unavailable';END IF;
 PERFORM pg_advisory_xact_lock(hashtext('partnership:'||auth.uid()));IF (SELECT count(*) FROM creator_partnerships WHERE sender_id=auth.uid() AND created_at>now()-interval '1 day')>=5 OR EXISTS(SELECT 1 FROM creator_partnerships WHERE sender_id=auth.uid() AND trainer_id=p_trainer AND created_at>now()-interval '1 hour') THEN RAISE EXCEPTION 'Inquiry limit reached; please wait';END IF;
 INSERT INTO creator_partnerships(trainer_id,sender_id,name,organization,email,collaboration,description,budget,timeline) VALUES(p_trainer,auth.uid(),trim(p_name),trim(p_organization),lower(trim(p_email)),trim(p_type),trim(p_description),trim(p_budget),trim(p_timeline)) RETURNING id INTO result;
 PERFORM creator_notify(p_trainer,'partnership:'||result,'New professional partnership inquiry.','/studio?section=messages-partnerships');RETURN result;
END $$;
CREATE FUNCTION public.update_creator_partnership(p_id uuid,p_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF NOT account_can_act(auth.uid(),false) OR p_status NOT IN ('new','discussion','accepted','declined','archived') THEN RAISE EXCEPTION 'Invalid inquiry status';END IF;UPDATE creator_partnerships SET status=p_status,updated_at=now() WHERE id=p_id AND trainer_id=auth.uid();IF NOT FOUND THEN RAISE EXCEPTION 'Not your partnership';END IF;END $$;
ALTER TABLE public.notification_preferences ADD COLUMN creator_updates boolean NOT NULL DEFAULT true;
ALTER TABLE public.notification_preferences ADD COLUMN subscriber_lives boolean NOT NULL DEFAULT false;
-- Preserve existing default preferences and historical notifications; new creator notices add one category.
DO $$ DECLARE c record;BEGIN FOR c IN SELECT conname FROM pg_constraint WHERE conrelid='public.account_notifications'::regclass AND contype='c' AND pg_get_constraintdef(oid) LIKE '%category%' LOOP EXECUTE format('ALTER TABLE public.account_notifications DROP CONSTRAINT %I',c.conname);END LOOP;END $$;
ALTER TABLE public.account_notifications ADD CONSTRAINT creator_notice_category CHECK(category IN ('session','credential','friend','milestone','moderation','poll','business'));
CREATE FUNCTION public.creator_notify(p_user uuid,p_key text,p_body text,p_href text DEFAULT '/studio') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM notification_preferences WHERE user_id=p_user AND NOT creator_updates) THEN PERFORM notify_account(p_user,p_key,'business',p_body,p_href);END IF;END $$;
CREATE TABLE public.creator_follow_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,trainer_id uuid NOT NULL REFERENCES auth.users(id),user_id uuid NOT NULL REFERENCES auth.users(id),followed boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX creator_follow_period ON public.creator_follow_events(trainer_id,created_at);
CREATE FUNCTION public.creator_track_follows() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE old_ids text[];new_ids text[];t text;following boolean;
BEGIN
 IF TG_OP='UPDATE' THEN old_ids=ARRAY(SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(OLD.extra->'followed')='array' THEN OLD.extra->'followed' ELSE '[]' END));ELSE old_ids='{}';END IF;
 new_ids=ARRAY(SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(NEW.extra->'followed')='array' THEN NEW.extra->'followed' ELSE '[]' END));
 FOR t IN SELECT DISTINCT unnest(old_ids||new_ids) LOOP
  IF (t=ANY(old_ids)) IS DISTINCT FROM (t=ANY(new_ids)) AND t ~* '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' AND t<>NEW.id::text AND EXISTS(SELECT 1 FROM profiles WHERE id=t::uuid AND role='trainer') THEN following=t=ANY(new_ids);INSERT INTO creator_follow_events(trainer_id,user_id,followed) VALUES(t::uuid,NEW.id,following);IF following THEN PERFORM creator_notify(t::uuid,'follow:'||NEW.id||':'||current_date,'A member followed your trainer profile.','/studio?section=analytics');END IF;END IF;
 END LOOP;RETURN NEW;
END $$;
CREATE TRIGGER creator_follow_history AFTER INSERT OR UPDATE OF extra ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.creator_track_follows();
CREATE TABLE public.creator_playbacks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id),video_id uuid NOT NULL REFERENCES public.trainer_videos(id),trainer_id uuid NOT NULL REFERENCES auth.users(id),reported_seconds integer NOT NULL DEFAULT 0 CHECK(reported_seconds BETWEEN 0 AND 18000),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX creator_playback_period ON public.creator_playbacks(trainer_id,created_at);
CREATE INDEX creator_playback_member ON public.creator_playbacks(user_id,created_at);
CREATE FUNCTION public.start_creator_playback(p_video uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE result uuid;t uuid;
BEGIN
 SELECT user_id INTO t FROM trainer_videos WHERE id=p_video;
 IF auth.uid() IS NULL OR t=auth.uid() OR NOT account_can_act(auth.uid(),false) OR NOT feedback_can_access(auth.uid(),p_video) THEN RAISE EXCEPTION 'Authorized member playback required';END IF;
 PERFORM pg_advisory_xact_lock(hashtext('playback:'||auth.uid()));IF (SELECT count(*) FROM creator_playbacks WHERE user_id=auth.uid() AND created_at>now()-interval '1 hour')>=120 THEN RAISE EXCEPTION 'Playback limit reached';END IF;
 INSERT INTO creator_playbacks(user_id,video_id,trainer_id) VALUES(auth.uid(),p_video,t) RETURNING id INTO result;RETURN result;
END $$;
CREATE FUNCTION public.report_creator_playback(p_id uuid,p_seconds integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN UPDATE creator_playbacks SET reported_seconds=greatest(reported_seconds,p_seconds),updated_at=now() WHERE id=p_id AND user_id=auth.uid() AND p_seconds BETWEEN 0 AND 18000 AND p_seconds<=extract(epoch FROM now()-created_at)+5 AND feedback_can_access(auth.uid(),video_id);IF NOT FOUND THEN RAISE EXCEPTION 'Invalid or expired playback checkpoint';END IF;END $$;
CREATE TABLE public.creator_perks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),category text NOT NULL CHECK(category IN ('education','equipment','business','growth')),partner text NOT NULL CHECK(length(trim(partner)) BETWEEN 1 AND 160),description text NOT NULL CHECK(length(trim(description)) BETWEEN 20 AND 3000),eligibility text NOT NULL CHECK(length(eligibility) BETWEEN 1 AND 1000),benefit text NOT NULL CHECK(length(benefit) BETWEEN 1 AND 500),expires_at timestamptz,redemption text NOT NULL CHECK(length(redemption) BETWEEN 1 AND 2000),url text CHECK(url ~ '^https://[^[:space:]]+$'),disclosure text NOT NULL CHECK(length(disclosure) BETWEEN 1 AND 1000),credential_pattern text NOT NULL DEFAULT '' CHECK(length(credential_pattern)<=100),published boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.school_tutorials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),audience text NOT NULL CHECK(audience IN ('creator','member','both')),category text NOT NULL CHECK(length(category) BETWEEN 1 AND 80),title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 160),instructions text NOT NULL DEFAULT '' CHECK(length(instructions)<=20000),screenshots jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(screenshots)='array' AND jsonb_array_length(screenshots)<=8),video_id uuid REFERENCES public.trainer_videos(id),published boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(),CHECK(NOT published OR length(trim(instructions))>=80));
CREATE INDEX school_search ON public.school_tutorials(audience,category,published);
CREATE FUNCTION public.guard_creator_resources() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE image jsonb;
BEGIN
 NEW.updated_at=now();IF TG_TABLE_NAME='school_tutorials' THEN
 FOR image IN SELECT value FROM jsonb_array_elements(NEW.screenshots) LOOP IF jsonb_typeof(image)<>'object' OR coalesce(image->>'url','') !~ '^https://[^[:space:]]+$' OR length(trim(coalesce(image->>'alt',''))) NOT BETWEEN 1 AND 300 THEN RAISE EXCEPTION 'Screenshots require HTTPS and an accessible description';END IF;END LOOP;
 IF NEW.published AND NEW.video_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM trainer_videos WHERE id=NEW.video_id AND review_status='approved' AND access_scope='public') THEN RAISE EXCEPTION 'Tutorial video must be approved and publicly accessible';END IF;
 END IF;RETURN NEW;
END $$;
CREATE TRIGGER school_resource_guard BEFORE INSERT OR UPDATE ON public.school_tutorials FOR EACH ROW EXECUTE FUNCTION public.guard_creator_resources();
CREATE TRIGGER perks_resource_guard BEFORE UPDATE ON public.creator_perks FOR EACH ROW EXECUTE FUNCTION public.guard_creator_resources();
DO $$ DECLARE title text;BEGIN FOREACH title IN ARRAY ARRAY['Set up your trainer profile','Upload certification evidence','Upload an on-demand workout','Configure water-break advertising','Host a scheduled class','Start a subscriber live','Manage your Trybe','Manage subscribers','Build a digital program','Track earnings and payouts','Manage bookings','Read your analytics','Manage your Trybe Store','Understand payment rules'] LOOP INSERT INTO school_tutorials(audience,category,title) VALUES('creator','Creator Academy',title);END LOOP;FOREACH title IN ARRAY ARRAY['Create your account','Find a trainer','Join a Trybe','Book a live class','Choose an optional subscription','Purchase a program','Track program progress','Manage payments','Use messages','Report a problem'] LOOP INSERT INTO school_tutorials(audience,category,title) VALUES('member','Member Help',title);END LOOP;END $$;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['creator_partnerships','creator_follow_events','creator_playbacks','creator_perks','school_tutorials'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated',t);EXECUTE format('GRANT ALL ON public.%I TO service_role',t);END LOOP;END $$;
GRANT SELECT ON public.creator_partnerships,public.creator_perks,public.school_tutorials TO authenticated;
GRANT SELECT ON public.school_tutorials TO anon;
GRANT INSERT,UPDATE,DELETE ON public.creator_perks,public.school_tutorials TO authenticated;
CREATE POLICY partnership_participants ON public.creator_partnerships FOR SELECT TO authenticated USING(trainer_id=auth.uid() OR sender_id=auth.uid());
CREATE POLICY verified_creator_perks ON public.creator_perks FOR SELECT TO authenticated USING(has_role(auth.uid(),'admin') OR (published AND (expires_at IS NULL OR expires_at>now()) AND trainer_is_eligible(auth.uid(),false)));
CREATE POLICY perks_admin ON public.creator_perks FOR ALL TO authenticated USING(has_role(auth.uid(),'admin')) WITH CHECK(has_role(auth.uid(),'admin'));
CREATE POLICY school_audience ON public.school_tutorials FOR SELECT TO anon,authenticated USING(has_role(auth.uid(),'admin') OR (published AND (audience IN ('member','both') OR EXISTS(SELECT 1 FROM profiles WHERE id=auth.uid() AND role='trainer' AND account_can_act(auth.uid(),false)))));
CREATE POLICY school_admin ON public.school_tutorials FOR ALL TO authenticated USING(has_role(auth.uid(),'admin')) WITH CHECK(has_role(auth.uid(),'admin'));
REVOKE ALL ON FUNCTION public.creator_price_limits(),public.guard_creator_price(),public.configure_creator_prices(integer,integer,integer),public.submit_creator_partnership(uuid,text,text,text,text,text,text,text),public.update_creator_partnership(uuid,text),public.creator_notify(uuid,text,text,text),public.creator_track_follows(),public.start_creator_playback(uuid),public.report_creator_playback(uuid,integer),public.guard_creator_resources() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.creator_price_limits() TO anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.configure_creator_prices(integer,integer,integer),public.submit_creator_partnership(uuid,text,text,text,text,text,text,text),public.update_creator_partnership(uuid,text),public.start_creator_playback(uuid),public.report_creator_playback(uuid,integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.creator_notify(uuid,text,text,text) TO service_role;
COMMIT;
